START TRANSACTION;;
CREATE TABLE "accounts_role" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "role_name" varchar(50) NOT NULL UNIQUE, "description" text NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "accounts_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "full_name" varchar(100) NOT NULL, "gender" varchar(10) NULL, "phone" varchar(20) NULL, "email" varchar(254) NOT NULL UNIQUE, "department" varchar(100) NULL, "status" varchar(20) NOT NULL, "profile_pic" varchar(100) NULL, "role_id" bigint NULL REFERENCES "accounts_role" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "assets_asset" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "asset_code" varchar(50) NOT NULL UNIQUE, "asset_name" varchar(150) NOT NULL, "serial_number" varchar(100) NULL UNIQUE, "barcode" varchar(100) NULL UNIQUE, "purchase_date" date NULL, "purchase_price" decimal NOT NULL, "warranty_expiry_date" date NULL, "asset_status" varchar(30) NOT NULL, "description" text NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "assigned_to_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "category_id" bigint NOT NULL REFERENCES "inventory_category" ("id") DEFERRABLE INITIALLY DEFERRED, "location_id" bigint NULL REFERENCES "inventory_location" ("id") DEFERRABLE INITIALLY DEFERRED, "supplier_id" bigint NULL REFERENCES "inventory_supplier" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "assets_assetauditlog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "audit_date" date NOT NULL, "condition_status" varchar(50) NOT NULL, "remarks" text NULL, "created_at" datetime NOT NULL, "asset_id" bigint NOT NULL REFERENCES "assets_asset" ("id") DEFERRABLE INITIALLY DEFERRED, "checked_by_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "location_id" bigint NULL REFERENCES "inventory_location" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "assets_assetdisposal" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "disposal_date" date NOT NULL, "disposal_reason" text NOT NULL, "disposal_value" decimal NOT NULL, "status" varchar(30) NOT NULL, "remarks" text NULL, "approved_at" datetime NULL, "created_at" datetime NOT NULL, "approved_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "asset_id" bigint NOT NULL REFERENCES "assets_asset" ("id") DEFERRABLE INITIALLY DEFERRED, "disposed_by_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "assets_assettransfer" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "transfer_number" varchar(30) NOT NULL UNIQUE, "transfer_date" date NOT NULL, "receive_date" date NULL, "approved_at" datetime NULL, "completed_at" datetime NULL, "status" varchar(20) NOT NULL, "reason" text NOT NULL, "notes" text NULL, "rejection_reason" text NULL, "attachment" varchar(100) NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "approved_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "asset_id" bigint NOT NULL REFERENCES "assets_asset" ("id") DEFERRABLE INITIALLY DEFERRED, "from_location_id" bigint NOT NULL REFERENCES "inventory_location" ("id") DEFERRABLE INITIALLY DEFERRED, "received_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "requested_by_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "to_location_id" bigint NOT NULL REFERENCES "inventory_location" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "assets_maintenancerecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "maintenance_date" date NOT NULL, "maintenance_type" varchar(50) NOT NULL, "issue_description" text NULL, "cost" decimal NOT NULL, "performed_by" varchar(100) NULL, "status" varchar(30) NOT NULL, "remarks" text NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "asset_id" bigint NOT NULL REFERENCES "assets_asset" ("id") DEFERRABLE INITIALLY DEFERRED, "created_by_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "assets_transferhistory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "old_status" varchar(20) NULL, "new_status" varchar(20) NOT NULL, "notes" text NULL, "timestamp" datetime NOT NULL, "changed_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "transfer_id" bigint NOT NULL REFERENCES "assets_assettransfer" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "inventory_category" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "category_name" varchar(100) NOT NULL, "category_type" varchar(50) NOT NULL, "description" text NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "inventory_inventoryitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "item_code" varchar(50) NOT NULL UNIQUE, "barcode" varchar(100) NULL UNIQUE, "item_name" varchar(150) NOT NULL, "unit" varchar(50) NOT NULL, "purchase_price" decimal NOT NULL, "current_qty" integer NOT NULL, "min_qty" integer NOT NULL, "description" text NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "category_id" bigint NOT NULL REFERENCES "inventory_category" ("id") DEFERRABLE INITIALLY DEFERRED, "supplier_id" bigint NULL REFERENCES "inventory_supplier" ("id") DEFERRABLE INITIALLY DEFERRED, "item_name_km" varchar(200) NULL);
CREATE TABLE "inventory_location" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "location_name" varchar(150) NOT NULL UNIQUE, "location_type" varchar(50) NOT NULL, "address" text NULL, "description" text NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "inventory_supplier" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "supplier_name" varchar(150) NOT NULL, "contact_person" varchar(100) NULL, "phone" varchar(20) NULL, "email" varchar(254) NULL, "address" text NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "notifications_notification" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "message" text NOT NULL, "notif_type" varchar(20) NOT NULL, "is_read" bool NOT NULL, "link" varchar(200) NULL, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "stock_lowstockalert" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "current_qty" integer NOT NULL, "min_qty" integer NOT NULL, "alert_date" datetime NOT NULL, "status" varchar(20) NOT NULL, "resolved_at" datetime NULL, "item_id" bigint NOT NULL REFERENCES "inventory_inventoryitem" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "stock_stockmovement" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "movement_type" varchar(20) NOT NULL, "quantity" integer NOT NULL, "movement_date" datetime NOT NULL, "reference_no" varchar(100) NULL, "reason" varchar(150) NULL, "remarks" text NULL, "qty_after" integer NULL, "created_at" datetime NOT NULL, "created_by_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "item_id" bigint NOT NULL REFERENCES "inventory_inventoryitem" ("id") DEFERRABLE INITIALLY DEFERRED);
